  if (out.numel() == 0) return out;

  musa_ops::MudnnTensorWrapper t_cond(cond_b);
  musa_ops::MudnnTensorWrapper t_self(self_b);
  musa_ops::MudnnTensorWrapper t_other(other_b);
  musa_ops::MudnnTensorWrapper t_out(out);
